import { NextResponse } from "next/server";
import { spawn } from "child_process";
import fs from "fs";
import path from "path";
import { getPlantInfo } from "../../lib/";

export const runtime = "nodejs";

export async function POST(request) {
  let tempImagePath = null;

  try {
    const body = await request.json();

    if (!body.image) {
      return NextResponse.json(
        {
          error: "No image provided.",
        },
        {
          status: 400,
        }
      );
    }

    // ------------------------------------
    // 1. Convert base64 image
    // ------------------------------------

    const base64Data = body.image.replace(
      /^data:image\/\w+;base64,/,
      ""
    );

    const buffer = Buffer.from(base64Data, "base64");

    const tempDir = path.join(process.cwd(), "temp");

    if (!fs.existsSync(tempDir)) {
      fs.mkdirSync(tempDir, {
        recursive: true,
      });
    }

    tempImagePath = path.join(
      tempDir,
      `plant-${Date.now()}.jpg`
    );

    fs.writeFileSync(tempImagePath, buffer);

    console.log("Image saved:", tempImagePath);

    // ------------------------------------
    // 2. Run Python ML model
    // ------------------------------------

    const pythonPath = "D:\\python\\python.exe";

    const modelPath =
      "D:\\major_project\\medicinal_plant_model\\predict.py";

    console.log("Running Python model...");

    const prediction = await new Promise(
      (resolve, reject) => {
        const python = spawn(pythonPath, [
          modelPath,
          tempImagePath,
        ]);

        let stdout = "";
        let stderr = "";

        python.stdout.on("data", (data) => {
          stdout += data.toString();
        });

        python.stderr.on("data", (data) => {
          stderr += data.toString();
        });

        python.on("error", (error) => {
          reject(error);
        });

        python.on("close", (code) => {
          if (code !== 0) {
            console.error(
              "Python error:",
              stderr
            );

            reject(
              new Error(
                stderr ||
                  `Python process exited with code ${code}`
              )
            );

            return;
          }

          try {
            // Python transformers prints loading information
            // to stderr, while JSON comes from stdout.
            const result = JSON.parse(
              stdout.trim()
            );

            resolve(result);
          } catch (error) {
            console.error(
              "Invalid Python output:",
              stdout
            );

            reject(
              new Error(
                "Could not parse Python prediction."
              )
            );
          }
        });
      }
    );

    console.log(
      "Python prediction:",
      prediction
    );

    const plant = prediction.plant;
    const confidence = prediction.confidence;

    // ------------------------------------
    // 3. Get plant information from LLM
    // ------------------------------------

    console.log(
      `Getting information for ${plant}...`
    );

    const plantInfo = await getPlantInfo(
      plant
    );

    // ------------------------------------
    // 4. Return everything to frontend
    // ------------------------------------

    return NextResponse.json({
      plant,
      confidence,
      properties: plantInfo,
      provider: plantInfo.provider,
    });
  } catch (error) {
    console.error(
      "Prediction error:",
      error
    );

    return NextResponse.json(
      {
        error:
          error.message ||
          "Prediction failed.",
      },
      {
        status: 500,
      }
    );
  } finally {
    // ------------------------------------
    // 5. Delete temporary image
    // ------------------------------------

    if (
      tempImagePath &&
      fs.existsSync(tempImagePath)
    ) {
      try {
        fs.unlinkSync(tempImagePath);
      } catch (error) {
        console.error(
          "Could not delete temp image:",
          error
        );
      }
    }
  }
}